#include <vector>
#include <unordered_map>

class Solution {
public:
    long long countStaircase(std::vector<int>& nums) {
        int n = nums.size();
        long long ans = 0;
        for (int i = 0; i < n; ++i) {
            std::vector<int> order;
            std::unordered_map<int, int> seen, freq;
            for (int j = i; j < n; ++j) {
                int x = nums[j];
                if (!seen.count(x)) {
                    seen[x] = order.size() + 1;
                    order.push_back(x);
                }
                freq[x]++;
                int k = order.size();
                int req = k * (k + 1) / 2;
                int cur = j - i + 1;
                if (cur == req) {
                    bool ok = true;
                    for (int v : order) {
                        if (freq[v] != seen[v]) { ok = false; break; }
                    }
                    if (ok) ans++;
                } else if (cur > req) {
                    break;
                }
            }
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int countStaircaseSubarraysII(int[] nums, int k) {
        int reqLen = k * (k + 1) / 2;
        int n = nums.length;
        if (n < reqLen) return 0;
        int total = 0;
        for (int i = 0; i <= n - reqLen; i++) {
            List<Integer> order = new ArrayList<>();
            Map<Integer, Integer> counts = new HashMap<>();
            for (int j = i; j < i + reqLen; j++) {
                int x = nums[j];
                if (!counts.containsKey(x)) order.add(x);
                counts.put(x, counts.getOrDefault(x, 0) + 1);
            }
            if (order.size() == k) {
                boolean valid = true;
                for (int m = 0; m < k; m++) {
                    if (counts.get(order.get(m)) != m + 1) {
                        valid = false;
                        break;
                    }
                }
                if (valid) total++;
            }
        }
        return total;
    }
}

var countStaircaseSubarraysII = function(nums, k) {
    const reqLen = Math.floor((k * (k + 1)) / 2);
    const n = nums.length;
    if (n < reqLen) return 0;
    let total = 0;
    for (let i = 0; i <= n - reqLen; i++) {
        const order = [];
        const counts = new Map();
        for (let j = i; j < i + reqLen; j++) {
            const x = nums[j];
            if (!counts.has(x)) order.push(x);
            counts.set(x, (counts.get(x) || 0) + 1);
        }
        if (order.length === k) {
            let valid = true;
            for (let m = 0; m < k; m++) {
                if (counts.get(order[m]) !== m + 1) {
                    valid = false;
                    break;
                }
            }
            if (valid) total++;
        }
    }
    return total;
};
